import kotlin.math.*

fun main() {
    val (r, x, y, x1, y1) = readLine()!!.split(" ").map { it.toLong() }
    val dx = x1 - x
    val dy = y1 - y
    val dist = sqrt(dx * dx + dy * dy)
    if (dist == 0.0) {
        println(0)
    } else {
        val steps = ceil(dist / (2 * r)).toLong()
        println(steps)
    }
}
